import java.util.Scanner;

public class Main {
    static long[] factorial = new long[501];
    static long[] InvFactorial = new long[501];
    static long[] f = new long[501];
    static long[] g = new long[501];
    static long[][][] h = new long[501][501][2];
    static long[][] C = new long[501][501];
    static long s, ans, F;
    static int n, m, mod, Mod, i, j, k, l;

    static long qpow(long a, int b) {
        long res = 1;
        while (b > 0) {
            if ((b & 1) == 1) res = res * a % mod;
            a = a * a % mod;
            b >>= 1;
        }
        return res;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        m = sc.nextInt();
        mod = sc.nextInt();
        Mod = mod - 2;

        factorial[0] = 1;
        for (i = 1; i <= n; i++) {
            factorial[i] = factorial[i - 1] * i % mod;
        }

        InvFactorial[n] = qpow(factorial[n], (int) Mod);
        for (i = n - 1; i >= 0; i--) {
            InvFactorial[i] = InvFactorial[i + 1] * (i + 1) % mod;
        }

        C[0][0] = 1;
        for (i = 1; i <= n; i++) {
            C[i][0] = 1;
            C[i][i] = 1;
            for (j = 1; j < i; j++) {
                C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % mod;
            }
        }

        f[0] = 1;
        g[0] = 0;

        for (i = 1; i <= m; i++) {
            for (j = 1; j <= i; j++) {
                s = (j * (j - 1) / 2 + (i - j + 1) * (i - j) / 2) % mod;
                // ADD(f[i], f[j - 1] * f[i - j] % mod * (i + 1) % mod * C[i - 1][j - 1]);
                long tempF = f[j - 1] * f[i - j] % mod * (i + 1) % mod * C[i - 1][j - 1] % mod;
                f[i] = (f[i] + tempF) % mod;

                long term1 = (g[j - 1] * f[i - j] + f[j - 1] * g[i - j]) % mod * (i + 1) % mod;
                long term2 = f[j - 1] * f[i - j] % mod * s % mod;
                long tempG = (term1 + term2) % mod * C[i - 1][j - 1] % mod;
                g[i] = (g[i] + tempG) % mod;
            }
        }

        // Initialize h array
        for (i = 0; i <= Math.min(m, n - m + 1) - 1; i++) {
            for (j = 0; j <= m - 1; j++) {
                for (k = 1; k <= m - j; k++) {
                    long F = f[k] * C[j + k][j] % mod;
                    h[i + 1][j + k][0] = (h[i + 1][j + k][0] + h[i][j][0] * F) % mod;
                    h[i + 1][j + k][1] = (h[i + 1][j + k][1] + h[i][j][1] * F) % mod;
                    long gTerm = g[k] * f[j] % mod * C[j + k][j] % mod;
                    h[i + 1][j + k][1] = (h[i + 1][j + k][1] + h[i][j][0] * gTerm) % mod;
                }
            }
        }

        for (i = 1; i <= Math.min(m, n - m + 1); i++) {
            ans = (ans + h[i][m][1] * C[n - m + 1][i]) % mod;
        }

        System.out.println((ans + mod) % mod);
        sc.close();
    }
}
